dt-example.js:
new DataTable('#example', {
	layout: {
		topStart: {
			buttons: ['stateCreate', 'statesList', 'pageLength']
		}
	},
	stateRestore: {
		predefined: [{
			name: 'Search - London',
			state: {
				search: {
					search: 'London'
				}
			}
		}, {
			name: 'Order - Position',
			state: {
				order: [[1, 'asc']]
			}
		}, {
			name: 'Search and order',
			state: {
				order: [[5, 'asc']],
				search: {
					search: 'San Francisco'
				}
			}
		}]
	}
});
